import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { courierProfile, initialOrders } from '../data/mock';

export const useCourier = create(
  persist(
    (set, get) => ({
      authed: false,
      online: false,
      courier: courierProfile,
      orders: initialOrders,
      toasts: [],

      login: (phone) => {
        set({ authed: true });
        get().pushToast('Xush kelibsiz, Jasur!', 'success');
      },

      logout: () => {
        set({ authed: false, online: false });
      },

      setOnline: (value) => {
        set({ online: value });
        get().pushToast(value ? 'Ish rejimi yoqildi' : 'Ish rejimi o\'chirildi', value ? 'success' : 'info');
      },

      acceptOrder: (id) => {
        set({ orders: get().orders.map((o) => (o.id === id ? { ...o, status: 'accepted' } : o)) });
        get().pushToast('Buyurtma qabul qilindi', 'success');
      },

      updateStatus: (id, status) => {
        set({ orders: get().orders.map((o) => (o.id === id ? { ...o, status } : o)) });
        const messages = {
          accepted: 'Buyurtma qabul qilindi',
          picked_up: 'Buyurtma olib olindi',
          on_the_way: 'Yo\'lga chiqdingiz',
          delivered: 'Buyurtma yetkazildi 🎉',
        };
        get().pushToast(messages[status] || 'Holat yangilandi', 'success');
      },

      pushToast: (message, type = 'success') => {
        const id = Date.now() + Math.random();
        set({ toasts: [...get().toasts, { id, message, type }] });
        setTimeout(() => get().dismissToast(id), 3200);
      },

      dismissToast: (id) => set({ toasts: get().toasts.filter((t) => t.id !== id) }),
    }),
    {
      name: 'maxshop-courier',
      partialize: (state) => ({ authed: state.authed, online: state.online, orders: state.orders }),
    },
  ),
);
